METHODS = ['_new_item_from_definition', '_normalize_item', '_add_item', '_can_move_item', '_move_item', '_place_page_at_pointer', '_create_sequence_row', '_update_sequence_row', '_sequence_row_signature', '_update_selection_controls']


def fail(message: str) -> None:
    raise SystemExit(f"ERREUR : {message}\nAucun fichier n'a été modifié.")


def replace_method(source: str, name: str, new_block: str) -> str:
    lines = source.splitlines(keepends=True)
    start = None
    for index, line in enumerate(lines):
        if line.startswith(f"    def {name}("):
            start = index
            break
    if start is None:
        fail(f"méthode {name} introuvable")

    end = len(lines)
    for index in range(start + 1, len(lines)):
        line = lines[index]
        if line.startswith("    def ") or line.startswith("    @"):
            end = index
            break

    return "".join(lines[:start]) + new_block.rstrip() + "\n\n" + "".join(lines[end:])


def main() -> None:
    if not TARGET.is_file():
        fail(f"fichier introuvable : {TARGET}")

    original = TARGET.read_text(encoding="utf-8")
    if NEW_MARKER in original:
        print("PLAN_GROUPES_DYNAMIQUES_DEJA_APPLIQUE")
        return
    if REQUIRED_MARKER not in original:
        fail(
            "le Plan du livre contextuel attendu n'est pas détecté. "
            "Par sécurité, la correction est refusée."
        )

    candidate = original
    for name in METHODS:
        candidate = replace_method(candidate, name, BLOCKS[name])

    candidate = candidate.replace(
        "# PLAN_DU_LIVRE_CONTEXTUEL_V1",
        "# PLAN_DU_LIVRE_CONTEXTUEL_V1\n        # PLAN_GROUPES_DYNAMIQUES_V1",
        1,
    )

    try:
        compile(candidate, str(TARGET), "exec")
    except Exception as exc:
        fail(f"la version préparée ne compile pas : {exc}")

    backup_dir = PROJECT / "cache" / "correctifs"
    backup_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = backup_dir / f"mockup_view_avant_groupes_dynamiques_{stamp}.py"
    temporary = TARGET.with_suffix(".groupes_dynamiques.tmp")

    try:
        temporary.write_text(candidate, encoding="utf-8")
        py_compile.compile(str(temporary), doraise=True)
        shutil.copy2(TARGET, backup)
        temporary.replace(TARGET)
        py_compile.compile(str(TARGET), doraise=True)
    except Exception as exc:
        try:
            temporary.unlink(missing_ok=True)
        except Exception:
            pass
        if backup.exists():
            shutil.copy2(backup, TARGET)
        fail(f"installation annulée automatiquement : {exc}")

    print("PLAN_GROUPES_DYNAMIQUES_OK")
    print("Fichier modifié : src/gui/views/mockup_view.py")
    print(f"Sauvegarde : {backup}")
    print("Pages auto : hauteur augmentée.")
    print("Monter/Descendre : disponibles immédiatement quand le déplacement est possible.")
    print("Ajout : insertion automatique à la suite du groupe choisi.")
    print("Déplacement : changement de groupe et de couleur lors du franchissement.")
    print("Ferme complètement PageMaître puis relance-le.")


if __name__ == "__main__":
    main()
